package VitaFortis.demo.v1.controller;
import VitaFortis.demo.v1.dto.ProdutoResponseDto; import VitaFortis.demo.v1.service.FavoritoService; import org.springframework.security.core.Authentication; import org.springframework.web.bind.annotation.*; import java.util.List;
@RestController @RequestMapping("/api/v1/usuarios/{usuarioId}/favoritos") public class FavoritoController {private final FavoritoService service;public FavoritoController(FavoritoService s){service=s;}@GetMapping public List<ProdutoResponseDto> listar(@PathVariable Long usuarioId,Authentication a){return service.listar(usuarioId,a.getName());}@PostMapping("/{produtoId}") public ProdutoResponseDto adicionar(@PathVariable Long usuarioId,@PathVariable Long produtoId,Authentication a){return service.adicionar(usuarioId,produtoId,a.getName());}@DeleteMapping("/{produtoId}") public void remover(@PathVariable Long usuarioId,@PathVariable Long produtoId,Authentication a){service.remover(usuarioId,produtoId,a.getName());}}
